<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use App\Models\{RoomType,Room,Guest,User,Reservation,Setting};
use App\Services\TrainingPolicy;
class GuestBookingFlowTest extends TestCase {
 use RefreshDatabase;
 private User $user;private RoomType $type;
 protected function setUp():void{parent::setUp();$g=Guest::create(['name'=>'Example Guest','email'=>'guest@example.test','phone'=>'+639123456789']);$this->user=User::factory()->create(['role'=>'guest','guest_id'=>$g->id,'email'=>$g->email]);$this->type=RoomType::create(['name'=>'Family','rate'=>1000,'capacity'=>4]);Room::create(['number'=>'101','room_type_id'=>$this->type->id]);Room::create(['number'=>'102','room_type_id'=>$this->type->id]);$this->actingAs($this->user);}
 private function room():array{return ['room_type_id'=>$this->type->id,'adults'=>2,'children'=>1,'child_ages'=>[7],'breakfast'=>'None','breakfast_pax'=>0,'services'=>[]];}
 private function data():array{return ['arrival'=>today()->addDay()->toDateString(),'departure'=>today()->addDays(2)->toDateString(),'rooms'=>[$this->room()],'reference'=>(string)Str::uuid(),'name'=>'Example Guest','email'=>'guest@example.test','email_confirmation'=>'guest@example.test','country'=>'Philippines','address'=>'Sample Street','city'=>'San Juan','phone'=>'09123456789','requests'=>'Quiet room','privacy'=>true,'payment_choice'=>'Later'];}
 public function test_multi_room_booking_is_atomic_and_idempotent():void{$d=$this->data();$d['rooms'][]=$this->room();$r=$this->postJson('/api/booking/confirm',$d)->assertCreated()->assertJsonCount(2,'reservations')->json();$this->assertDatabaseCount('reservations',2);$this->assertNull($r['reservations'][0]['room_id']);$this->assertSame([7],$r['reservations'][0]['booking_details']['child_ages']);$this->postJson('/api/booking/confirm',$d)->assertOk()->assertJsonPath('replayed',true);$this->assertDatabaseCount('reservations',2);$this->assertDatabaseCount('confirmation_letters',2);$this->assertDatabaseCount('payments',0);}
 public function test_insufficient_inventory_does_not_partially_book():void{$d=$this->data();$d['rooms']=[$this->room(),$this->room(),$this->room()];$this->postJson('/api/booking/confirm',$d)->assertUnprocessable();$this->assertDatabaseCount('reservations',0);$this->assertDatabaseCount('guest_booking_requests',0);}
 public function test_quote_and_booking_use_server_services_and_tax():void{Setting::create(['key'=>'booking_services','value'=>[['id'=>'extra','name'=>'Sample extra','price'=>250,'active'=>true]]]);Setting::create(['key'=>'training_policy','value'=>[...TrainingPolicy::defaults(),'local_tax_percent'=>10]]);$d=$this->data();$d['rooms'][0]['services']=[['id'=>'extra','quantity'=>2,'price'=>1]];$this->postJson('/api/booking/quote',$d)->assertOk()->assertJsonPath('total',1650)->assertJsonPath('rooms.0.pricing.services_total',500);$r=$this->postJson('/api/booking/confirm',[...$d,'amount'=>1])->assertCreated()->json('reservations.0');$this->assertEquals(1650,$r['amount']);$this->assertSame('Sample extra',$r['pricing']['services'][0]['name']);$changed=$this->putJson('/api/reservations/'.$r['id'].'/dates',['arrival'=>today()->addDays(2)->toDateString(),'departure'=>today()->addDays(4)->toDateString()])->assertOk()->json();$this->assertEquals(3300,$changed['amount']);$this->assertEquals(1000,$changed['pricing']['services_total']);$this->assertEquals(2,$changed['pricing']['services'][0]['nights']);}
 public function test_child_ages_and_guest_identity_are_validated():void{$d=$this->data();$d['rooms'][0]['child_ages']=[];$this->postJson('/api/booking/quote',$d)->assertUnprocessable();$d=$this->data();$d['email']=$d['email_confirmation']='other@example.test';$this->postJson('/api/booking/confirm',$d)->assertUnprocessable();$this->assertDatabaseCount('reservations',0);}
 public function test_guest_cannot_manage_service_catalog_or_reuse_reference_for_new_payload():void{$this->postJson('/api/booking/services',['services'=>[]])->assertForbidden();$d=$this->data();$this->postJson('/api/booking/confirm',$d)->assertCreated();$d['requests']='Changed request';$this->postJson('/api/booking/confirm',$d)->assertConflict();$this->assertDatabaseCount('reservations',1);}
 public function test_quote_rejects_inactive_services_and_confirmation_requires_login():void{Setting::create(['key'=>'booking_services','value'=>[['id'=>'off','name'=>'Unavailable','price'=>5,'active'=>false]]]);$d=$this->data();$d['rooms'][0]['services']=[['id'=>'off','quantity'=>1]];$this->postJson('/api/booking/quote',$d)->assertUnprocessable();auth()->logout();$this->postJson('/api/booking/confirm',$this->data())->assertUnauthorized();}
 public function test_online_booking_continues_during_night_audit_but_payments_wait():void{Setting::create(['key'=>'business_date_Hotel','value'=>['date'=>today()->subDay()->toDateString()]]);$r=$this->postJson('/api/booking/confirm',$this->data())->assertCreated()->json('reservations.0');$this->postJson('/api/paymongo/checkout',['reference'=>(string)Str::uuid(),'method'=>'qrph','allocations'=>[['reservation_id'=>$r['id'],'amount'=>100]]])->assertUnprocessable();$this->assertDatabaseCount('payments',0);}
}
